Ещё один мод для работы с музыкальными релизами. Добавляете после поля Продолжительность и поле будет подсчитывать общую продолжительность перетянутых на него аудио-файлов (только файлы поддерживаемые вашим браузером).<br />
Для установки добавьте в конце <b>styles\templates\posting_tpl.tpl</b>:<br />
<pre class="xfBb-code" data-lang="html">&lt;!--drag_drop_duration--&gt;
&lt;style&gt;
    input.drag-over {
        border: dashed;
        border-radius: 5px;
    }
&lt;/style&gt;
&lt;script&gt;
    TPL.el_id = Object.assign({drag_drop_duration: &#039;Drag and Drop продолжительность&#039;}, TPL.el_id);
    $(&#039;body&#039;)
        .on(&#039;drop&#039;, &#039;input[type=text]&#039;, e =&gt; {
            if ($(e.target).parent().has(&#039;.drag_drop_duration&#039;).length) {
                e.preventDefault();
                let files = e.originalEvent.target.files || e.originalEvent.dataTransfer.files,
                    audios = new Set,
                    duration = 0;
                $.each(files, (i, file) =&gt; {
                    let audio = new Audio(URL.createObjectURL(file));
                    audio.oncanplaythrough = () =&gt; {
                        duration += audio.duration;
                        audios.delete(audio);
                        if (!audios.size) {
                            let date = new Date(1970, 0, 1);
                            date.setSeconds(Math.round(duration));
                            $(e.target).val(date.toTimeString().replace(/(\d\d:\d\d:\d\d).*/, &#039;$1&#039;));
                        }
                    };
                    audios.add(audio);
                });
            }
            $(e.target).removeClass(&#039;drag-over&#039;);
        })
        .on(&#039;dragover&#039;, &#039;input[type=text]&#039;, e =&gt; {
            if ($(e.target).parent().has(&#039;.drag_drop_duration&#039;).length) {
                e.preventDefault();
                $(e.target).addClass(&#039;drag-over&#039;);
            }
        })
        .on(&#039;dragleave&#039;, &#039;input[type=text]&#039;, e =&gt; {
            $(e.target).removeClass(&#039;drag-over&#039;);
        });
&lt;/script&gt;
&lt;div id=&quot;drag_drop_duration&quot; style=&quot;display: none&quot;&gt;
    &lt;span class=&quot;drag_drop_duration&quot;&gt;&lt;/span&gt;
&lt;/div&gt;
&lt;!--/drag_drop_duration--&gt;</pre>Пример работы:<br />
